import {conditionList,channel,incapacitated,immobilized} from './conditions.js';
import {KEYS,NAMES,balanced,valid,total,derived,newBattle,actor,alive,dist,budget,pathCheck,move,act,canAct,aiTurn,ACTIONS,efficiencies,previewAction,MOVEMENT_MODES,route,routeTo,fitPath,directReach,face,engaged,ENGAGEMENT_REACH,engagementReady,facingArc,phase,timelineRows,REACTIONS,setReaction,stepTimeline,previewMoveTiming,combatDefense,DAMAGE_TYPES,exertion,recoveryRates,forecastResources} from './engine.js';
import {MAPS,makeMap,MAP_TEMPLATES} from './maps.js';
import {visibleTo,canSee,groundAt,visibilityCells} from './battlefield.js';
import {clone,character,team,bounded,clean,generate,parseRoster,rosterFile} from './rosters.js';
import {snapshot,restore} from './persistence.js';
const root=document.querySelector('#app');document.body.classList.add('ascendant-mode');root.classList.add('ascendant-root');
const icon=new URL('./icons/icon-192.png',import.meta.url).href;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>Array.from({length:2},(_,i)=>Array.from({length:5},(_,j)=>({name:`${i?'Enemy':'Ally'} ${j+1}`,stats:balanced(),locks:[]})));
let teams=defaults(),mapId=0,tab=0,edit=0,b=null,path=[],targetId=null,inspectId=null,push=exertion(false),auto=false,paused=false,delay=300,timer=null,view=null,mode='move',note='',showLog=false,seedInput='';
let replayIndex=-1;
let mapSeed=0,mapWidth=0,mapHeight=0,mapDeployment=6,mapFog=true,mapElevation=true,mapHazards=true,selectedMap=null,sightView='team';
function chosenMap(){return selectedMap??=makeMap(mapId,mapSeed,{width:mapWidth,height:mapHeight,deployment:mapDeployment,fog:mapFog,elevation:mapElevation,hazards:mapHazards});}
const visible=u=>!!u&&(!b||b.winner!==null||visibleTo(b,0,u));
function shownUnits(){return b.units.filter(visible);}
function fogMarkup(map){if(!map.fog||b.winner!==null)return '';const observer=sightView==='individual'?(b.units.find(u=>u.id===inspectId&&u.team===0)||b.units.find(u=>u.team===0&&u.hp>0)):null;return visibilityCells(b,0).filter(q=>observer?!canSee(map,observer,{x:q.x+q.w/2,y:q.y+q.h/2}):!q.visible).map(q=>`<rect x="${q.x}" y="${q.y}" width="${q.w}" height="${q.h}" fill="#091619" fill-opacity=".48" pointer-events="none"/>`).join('');}
function lastSeenMarkup(){if(!b.map.fog||b.winner!==null)return '';return Object.entries(b.contacts?.[0]||{}).filter(([id,p])=>p.hp>0&&!visible(b.units.find(u=>u.id===id))&&b.time-p.time<20).map(([id,p])=>`<g pointer-events="none"><circle cx="${p.x}" cy="${p.y}" r=".5" fill="none" stroke="#e3a39b" stroke-width=".08" stroke-dasharray=".12 .12"/><text x="${p.x}" y="${p.y+.18}" text-anchor="middle" font-size=".43" fill="#e3a39b">?</text></g>`).join('');}
function mapFeatures(map){return (map.elevation||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" rx=".35" fill="#83a6b5" fill-opacity=".16" stroke="#a2c0d2" stroke-width=".08"/><rect x="${o.x+o.ramp/2}" y="${o.y+o.ramp/2}" width="${o.w-o.ramp}" height="${o.h-o.ramp}" rx=".2" fill="none" stroke="#a2c0d2" stroke-width=".07" stroke-dasharray=".2 .15"/><text x="${o.x+o.w/2}" y="${o.y+.6}" text-anchor="middle" font-size=".46" fill="#c8e3ef">+${o.height.toFixed(1)}m</text></g>`).join('')+(map.hazards||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#e99b78" fill-opacity=".19" stroke="#ec987a" stroke-dasharray=".17 .17" stroke-width=".1"/><text x="${o.x+o.w/2}" y="${o.y+.5}" text-anchor="middle" font-size=".46" fill="#ffd0b5">${esc(o.kind)}</text></g>`).join('');}
function arenaOptions(){return `<div class="ascendant-arena-options"><label>Map variation seed<input id="ascendant-map-seed" type="number" min="0" max="4294967295" value="${mapSeed}"></label><button data-do="rollMapSeed">New variation</button><label>Width (m)<input id="ascendant-width" type="number" min="26" max="64" value="${chosenMap().w}"></label><label>Height (m)<input id="ascendant-height" type="number" min="20" max="48" value="${chosenMap().h}"></label><label>Deployment depth (m)<input id="ascendant-deployment" type="number" min="4" max="8" value="${chosenMap().zones[0].w}"></label><label><input type="checkbox" id="ascendant-fog" ${mapFog?'checked':''}> Fog of war</label><label><input type="checkbox" id="ascendant-elevation" ${mapElevation?'checked':''}> Raised terrain</label><label><input type="checkbox" id="ascendant-hazards" ${mapHazards?'checked':''}> Environmental hazards</label></div>`;}

let moveKind='run',waypoint=-1,showReach=true,showThreat=true;
let library=[],teamNames=['Team A','Team B'],initial=null,savedBattle=null,storageNote='',setupNote='',libraryOpen=false,importKind=null;
const read=k=>{try{return JSON.parse(localStorage.getItem(k));}catch{return null;}};
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{storageNote='Local storage unavailable or full. Export important data before leaving.';return false;}}
const saved=read('ascendant.setup.v1');if(saved?.teams?.length===2&&saved.teams.every(t=>Array.isArray(t)&&t.length===5&&t.every(c=>typeof c.name==='string'&&bounded(c.stats)))){teams=saved.teams.map(t=>t.map(clean));mapId=Math.max(0,Math.min(19,Number(saved.mapId)||0));teamNames=Array.isArray(saved.teamNames)&&saved.teamNames.length===2?saved.teamNames.map(v=>String(v).slice(0,32)):teamNames;seedInput=String(saved.seedInput??'');mapSeed=Number(saved.mapSeed)>>>0;mapWidth=Number(saved.mapWidth)||0;mapHeight=Number(saved.mapHeight)||0;mapDeployment=Number(saved.mapDeployment)||6;mapFog=saved.mapFog!==false;mapElevation=saved.mapElevation!==false;mapHazards=saved.mapHazards!==false;}
const lib=read('ascendant.library.v1');if(Array.isArray(lib))library=lib.filter(v=>v&&typeof v.name==='string'&&(v.kind==='character'?character(v.data):v.kind==='team'&&team(v.data)));
try{const x=read('ascendant.battle.v1');if(x){restore(x);savedBattle=x;}}catch{storageNote='An incompatible saved battle could not be restored.';}
function save(){store('ascendant.setup.v1',{teams,mapId,teamNames,seedInput,mapSeed,mapWidth,mapHeight,mapDeployment,mapFog,mapElevation,mapHazards});}
function saveBattle(){if(!b)return;const x=snapshot(b,initial,{path,targetId,inspectId,push,view,mode,delay,auto,paused,moveKind,waypoint,showReach,showThreat,sightView});if(store('ascendant.battle.v1',x))savedBattle=x;}
function resume(){if(!savedBattle)return;try{b=restore(savedBattle);initial=clone(savedBattle.initial);const u=savedBattle.ui||{};path=Array.isArray(u.path)?clone(u.path):[];targetId=u.targetId??null;inspectId=u.inspectId??b.active;push=exertion(u.push);view=u.view??null;mode=['pan','move','route','face'].includes(u.mode)?u.mode:'move';moveKind=Object.hasOwn(MOVEMENT_MODES,u.moveKind)?u.moveKind:'run';waypoint=Number.isInteger(u.waypoint)&&u.waypoint>0&&u.waypoint<path.length?u.waypoint:-1;showReach=u.showReach!==false;showThreat=u.showThreat!==false;sightView=u.sightView==='individual'?'individual':'team';delay=[40,300,650].includes(u.delay)?u.delay:300;auto=!!u.auto;paused=true;note='Saved battle restored. AI paused until you resume.';render();}catch(e){setupNote=e.message;render();}}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function saveLibrary(kind){const data=kind==='team'?teams[tab]:teams[tab][edit];if(!(kind==='team'?team(data):character(data))){setupNote='Complete the 200-point allocation before saving.';return;}const name=kind==='team'?teamNames[tab]:data.name;library.push({kind,name,data:clone(data)});store('ascendant.library.v1',library);libraryOpen=true;setupNote=`Saved ${name} to library.`;}
function applyLibrary(index){const item=library[index];if(!item)return;if(item.kind==='team') {teams[tab]=clone(item.data);teamNames[tab]=item.name.slice(0,32);}else teams[tab][edit]=clone(item.data);save();setupNote=`Loaded ${item.name}.`;}
function rosterTools(){return `<div class="ascendant-editor-tools"><button data-do="saveCharacter">Save character</button><button data-do="copyCharacter">Duplicate to…</button><button data-do="exportCharacter">Export</button><button data-do="importCharacter">Import</button><button data-do="saveTeam">Save team</button><button data-do="copyTeam">Copy team to other side</button><button data-do="exportTeam">Export team</button><button data-do="importTeam">Import team</button><button data-do="library" class="${libraryOpen?'on':''}">Library (${library.length})</button></div><input type="file" hidden id="ascendant-import" accept=".json,application/json">${libraryOpen?`<div class="ascendant-library"><h3>Saved rosters</h3>${library.length?library.map((v,i)=>`<div class="ascendant-library-row"><span><b>${esc(v.name)}</b><small>${v.kind}</small></span><button data-load="${i}">Load</button><button data-rename="${i}">Rename</button><button data-duplicate="${i}">Copy</button><button data-delete="${i}">Delete</button></div>`).join(''):'<p class="ascendant-muted">No saved rosters yet.</p>'}</div>`:''}<p class="ascendant-message" role="status">${esc(setupNote||storageNote)}</p>`;}
function derivedPanel(s){const d=derived(s);return [['HP',d.hp],['Mana',d.mana],['Physical',d.physical],['Mental',d.mental],['Resolve',d.resolve],['Move (m)',d.move],['REA timing ref.',d.delay],['DR',d.dr],['RES (%)',d.res*100],['Mental DR',2*((s.END+s.WIL)/40)**.8],['Sight (m)',d.sight]].map(([k,v])=>`<span>${k}<b>${v.toFixed(1)}</b></span>`).join('');}
function header(sub){return `<header class="ascendant-head"><div class="ascendant-brand"><img src="${icon}" alt=""><div><h1>Ascendant <small>v0.1.7</small></h1><p>${sub}</p></div></div><div class="ascendant-head-actions">${b?'<button data-do="setup">Save & setup</button>':''}${globalThis.__APP_LAUNCHER__?'<button data-do="home">Home</button><button data-do="update" aria-label="Check updates">↻</button>':'<button data-do="update" aria-label="Check updates">↻</button>'}</div></header>`;}
function movementOverlay(c){if(!c||!b||b.moved||!showReach)return '';const p=directReach(b,path,push,moveKind,48);return p.length?`<polygon points="${p.map(q=>`${q.x},${q.y}`).join(' ')}" fill="#80d0ff" fill-opacity=".08" stroke="#8fc8e9" stroke-width=".065" stroke-opacity=".6" stroke-dasharray=".25 .14" pointer-events="none"/>`:'';}
function threatOverlay(c){if(!c||!showThreat)return '';return alive(b).filter(u=>u.team!==c.team&&visible(u)).map(u=>`<circle cx="${u.x}" cy="${u.y}" r="${ENGAGEMENT_REACH}" fill="#ec8078" fill-opacity="${engagementReady(u)?'.10':'.025'}" stroke="#ed9588" stroke-width=".07" stroke-opacity="${engagementReady(u)?'.8':'.35'}" stroke-dasharray=".25 .14" pointer-events="none"/>`).join('');}
function pathMarkup(check){if(path.length<2)return '';const col=check?.ok?'#8be6bf':'#ff9b89';return `<polyline id="ascendant-path-line" points="${path.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${col}" stroke-width=".14" stroke-linejoin="round" pointer-events="none"/>${path.slice(1).map((p,j)=>{const i=j+1,a=path[j],mid={x:(a.x+p.x)/2,y:(a.y+p.y)/2};return `<g data-insert="${i}" class="ascendant-insert"><circle cx="${mid.x}" cy="${mid.y}" r=".29" fill="#152e34" stroke="#a7c4c5" stroke-width=".06"/><path d="M${mid.x-.13} ${mid.y}h.26 M${mid.x} ${mid.y-.13}v.26" stroke="#b9cfcd" stroke-width=".055" pointer-events="none"/></g><g data-waypoint="${i}"><circle cx="${p.x}" cy="${p.y}" r=".45" fill="transparent" stroke="transparent" stroke-width="10" vector-effect="non-scaling-stroke"/><circle cx="${p.x}" cy="${p.y}" r=".25" fill="${waypoint===i?'#f4e7a4':col}" stroke="#14282d" stroke-width=".08" pointer-events="none"/><text x="${p.x}" y="${p.y+.12}" fill="#17282b" font-size=".34" font-weight="bold" text-anchor="middle" pointer-events="none">${i}</text></g>`;}).join('')}${(check?.threats||[]).map(t=>`<circle cx="${t.point.x}" cy="${t.point.y}" r=".3" fill="#f4b36c" stroke="#4e291a" stroke-width=".07" pointer-events="none"/>`).join('')}`;}
function movementPanel(c,manual,check){const summary=check||(b.moved?b.lastMove:null),used=summary?.total??(b.moved&&c?b.moveSpent*c.max.move:0),m=summary?.limit??(c?budget(c,push,moveKind):0),threats=check?.threats||[],mt=check?.ok&&c?previewMoveTiming(c,check,push,moveKind):null,forecast=mt?forecastResources(c,'move',mt,check.energy,push).end:null;return `<div class="ascendant-movement-panel"><div class="ascendant-mode-grid">${Object.entries(MOVEMENT_MODES).map(([k,v])=>`<button data-movement="${k}" class="${moveKind===k?'on':''}" ${!manual||b.moved||(c&&budget(c,push,moveKind)<=0)?'disabled':''}><b>${v.label}</b><small>${c?budget(c,push,k).toFixed(1):'0'} m</small></button>`).join('')}</div><div class="ascendant-movement"><div><b>${used.toFixed(2)} / ${m.toFixed(2)} m</b> ${b.moved?'· used':'movement budget'}<small>${summary?`${summary.reason} · ${summary.energy?summary.energy.physical.toFixed(1)+' P / '+summary.energy.mental.toFixed(1)+' M / '+summary.energy.resolve.toFixed(1)+' R':''}`:b.moved?'Movement is complete for this turn.':mode==='route'?'Tap ground for an automatic route, clipped to this turn.':mode==='face'?'Tap a point or character to face it.':'Tap ground to add segments. Drag numbered points; tap + to insert.'}</small></div></div><div class="ascendant-budget-track"><i style="width:${Math.min(100,m?used/m*100:0)}%;background:${summary?.ok?'#8be6bf':'#ed947f'}"></i></div><div class="ascendant-move-breakdown">${[['Distance',summary?.length],['Momentum',summary?.turn],['Terrain',summary?.terrain]].map(([n,v])=>`<span>${n}<b>${(v??0).toFixed(2)} m</b></span>`).join('')}</div>${check?.ok&&c?`<p class="ascendant-muted">Movement time ${Object.values(previewMoveTiming(c,check,push,moveKind)).reduce((a,b)=>a+b,0).toFixed(2)}s · other actions may resolve during travel.${forecast?` Est. after movement: ${forecast.physical.toFixed(1)} P / ${forecast.mental.toFixed(1)} M / ${forecast.resolve.toFixed(1)} R.`:""}</p>`:''}${threats.length?`<p class="ascendant-risk" role="status">Interception risk: ${threats.map(t=>esc(t.name)).join(', ')}. Cautious movement reduces hit chance; each opponent can intercept once per own turn.</p>`:''}${check?.hazards?.length?`<p class="ascendant-risk">Hazards on path: ${check.hazards.map(h=>esc(h.kind)+" ("+h.length.toFixed(1)+" m)").join(", ")}. Recovery forecasts exclude hazard damage and exposure.</p>`:""}${c&&engaged(b,c).length?`<p class="ascendant-muted">Engaged by ${engaged(b,c).map(u=>esc(u.name)).join(', ')}.</p>`:''}<div class="ascendant-buttons ascendant-waypoint-tools"><button data-do="undo" ${!manual||path.length<2?'disabled':''}>Undo</button><button data-do="deleteWaypoint" ${!manual||waypoint<1||waypoint>=path.length?'disabled':''}>Delete point ${waypoint>0?waypoint:''}</button><button data-do="clear" ${!manual||path.length<2?'disabled':''}>Clear</button><button data-do="routeTarget" ${!manual||b.moved||!b.units.some(u=>u.id===targetId&&u.team!==c?.team&&u.hp>0&&visible(u))?'disabled':''}>Route to target</button><button data-do="fitPath" ${!manual||path.length<2||check?.ok?'disabled':''}>Trim path</button><button data-do="move" class="ascendant-primary" ${!manual||!check?.ok?'disabled':''}>Move</button></div></div>`;}
function mapSVG(map,interactive=false){const colors={grass:'#263d35',sand:'#4a4030',stone:'#343d43',forest:'#233b35'},objects={stone:'#7b8b93',wood:'#a48960',rubble:'#6a777c',hedge:'#5e8058'},c=b&&actor(b),target=b?.units.find(u=>u.id===targetId),check=path.length>1&&b?pathCheck(b,path,push,moveKind):null;const vb=interactive&&view?`${view.x} ${view.y} ${view.w} ${view.h}`:`0 0 ${map.w} ${map.h}`;return `<svg ${interactive?'id="ascendant-board" tabindex="0" aria-label="Interactive battlefield"':'aria-label="Map preview"'} viewBox="${vb}" style="aspect-ratio:${map.w}/${map.h}" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="ascendant-grid" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" stroke="#b1c4bc" stroke-opacity=".12" stroke-width=".035" fill="none"/></pattern></defs><rect width="${map.w}" height="${map.h}" fill="${colors[map.theme]}"/><rect width="${map.w}" height="${map.h}" fill="url(#ascendant-grid)"/>${map.zones.map((z,i)=>`<rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" fill="${i?'#e5746b':'#62b5e6'}" fill-opacity=".12" stroke="${i?'#df857b':'#87c7ef'}" stroke-width=".08" stroke-dasharray=".4 .3"/><text x="${z.x+z.w/2}" y="${z.y+.9}" font-size=".65" fill="#e0e5dc" text-anchor="middle">${i?'TEAM B':'TEAM A'}</text>`).join('')}${(map.terrain||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#d4bd78" fill-opacity=".13" stroke="#d4bd78" stroke-opacity=".5" stroke-dasharray=".22 .17" stroke-width=".06"/><text x="${o.x+o.w/2}" y="${o.y+o.h/2}" text-anchor="middle" font-size=".38" fill="#ecdda7">${esc(o.kind)} ×${o.factor}</text></g>`).join('')}${mapFeatures(map)}${map.obstacles.map(o=>`<rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" rx=".1" fill="${objects[o.kind]}" opacity="${o.height!==undefined&&o.height<1.2?.72:1}" stroke="#172b2c" stroke-width=".13"/><path d="M${o.x+.18} ${o.y+o.h-.18}V${o.y+.18}H${o.x+o.w-.18}" fill="none" stroke="#fff" stroke-opacity=".22" stroke-width=".10"/>`).join('')}${interactive?fogMarkup(map)+lastSeenMarkup():''}${interactive&&c&&c.team===0?movementOverlay(c)+threatOverlay(c):''}${interactive&&c&&visible(c)&&visible(target)?`<line x1="${c.x}" y1="${c.y}" x2="${target.x}" y2="${target.y}" stroke="#edca85" stroke-width=".08" stroke-dasharray=".25 .2"/>`:''}${interactive?shownUnits().filter(u=>u.hp>0&&u.job?.phase!=='recovery'&&u.job).map(u=>{const j=u.job,col=u.team?'#f3a29a':'#8fc8e9',t=b.units.find(v=>v.id===j.target);return j.key==='move'?`<polyline points="${[[u.x,u.y],...j.steps.slice(j.index).map(q=>[q.point.x,q.point.y])].map(q=>q.join(',')).join(' ')}" stroke="${col}" stroke-width=".10" stroke-opacity=".68" stroke-dasharray=".20 .15" fill="none" pointer-events="none"/>`:ACTIONS[j.key]?.reach&&t?.hp>0&&visible(t)?`<line x1="${u.x}" y1="${u.y}" x2="${t.x}" y2="${t.y}" stroke="${col}" stroke-width=".13" stroke-opacity=".65" stroke-dasharray=".15 .12" pointer-events="none"/>`:'';}).join(''):''}${interactive?shownUnits().map(u=>{const active=u.id===b.active,sel=u.id===inspectId,tar=u.id===targetId,dead=u.hp<=0,col=u.team?'#e68179':'#79c4ee';return `<g data-unit="${u.id}" opacity="${dead?.36:1}"><circle cx="${u.x}" cy="${u.y}" r=".85" fill="transparent"/>${active?`<circle cx="${u.x}" cy="${u.y}" r=".68" fill="none" stroke="#f4e7a4" stroke-width=".13"/>`:''}${sel?`<circle cx="${u.x}" cy="${u.y}" r=".82" fill="none" stroke="#fff" stroke-width=".09"/>`:''}${tar?`<circle cx="${u.x}" cy="${u.y}" r=".96" fill="none" stroke="#ffb17b" stroke-width=".13" stroke-dasharray=".2 .12"/>`:''}<circle cx="${u.x}" cy="${u.y}" r=".48" fill="${dead?'#6c7474':col}" stroke="#102226" stroke-width=".09"/><text x="${u.x}" y="${u.y+.18}" font-size=".48" font-weight="bold" text-anchor="middle" fill="#17282b">${dead?'×':u.id.slice(1)}</text>${!dead?`<path d="M${u.x+.5*Math.cos(u.facing)} ${u.y+.5*Math.sin(u.facing)} L${u.x+.79*Math.cos(u.facing)} ${u.y+.79*Math.sin(u.facing)}" stroke="#fff5d6" stroke-width=".13" stroke-linecap="round" pointer-events="none"/>`:''}<rect x="${u.x-.55}" y="${u.y-.82}" width="1.1" height=".12" rx=".04" fill="#19282a"/><rect x="${u.x-.55}" y="${u.y-.82}" width="${1.1*u.hp/u.max.hp}" height=".12" rx=".04" fill="${col}"/>${!dead&&statusText(u)?`<circle cx="${u.x+.58}" cy="${u.y-.50}" r=".15" fill="#e5c280" stroke="#19282a" stroke-width=".04"/><title>${esc(statusText(u))}</title>`:''}</g>`;}).join(''):''}${interactive?pathMarkup(check):''}</svg>`;}
function renderSetup(){const ch=teams[tab][edit],s=ch.stats,t=total(s),all=teams.every(t=>t.every(c=>valid(c.stats)));root.innerHTML=`${header('Tactical battleground · prototype')}${savedBattle?`<div class="ascendant-resume-banner"><span>Saved battle · turn ${savedBattle.state.turns} · seed ${savedBattle.state.seed}</span><button class="ascendant-primary" data-do="resume">Resume</button></div>`:''}<main class="ascendant-setup"><section class="ascendant-panel"><div class="ascendant-section-title"><div><span class="ascendant-kicker">01 / ROSTERS</span><h2>Assemble both teams</h2></div><span class="ascendant-pill ${all?'ok':'warn'}">${teams.flat().filter(c=>valid(c.stats)).length}/10 ready</span></div><div class="ascendant-tabs"><button data-tab="0" class="${tab===0?'on':''}">${esc(teamNames[0])} · You</button><button data-tab="1" class="${tab===1?'on':''}">${esc(teamNames[1])} · AI</button></div><label class="ascendant-team-name">Team name <input id="ascendant-team-name" maxlength="32" value="${esc(teamNames[tab])}"></label><div class="ascendant-roster">${teams[tab].map((c,i)=>`<button data-edit="${i}" class="${edit===i?'on':''}"><b>${esc(c.name)}</b><small>${total(c.stats)} / 200 ${valid(c.stats)?'✓':''}</small></button>`).join('')}</div><div class="ascendant-editor-head"><label>Character name<input id="ascendant-name" maxlength="24" value="${esc(ch.name)}"></label><div><span class="ascendant-kicker">POINTS REMAINING</span><strong class="${t===200?'ascendant-good':'ascendant-warn'}" id="ascendant-left">${200-t}</strong></div></div><div class="ascendant-stats">${KEYS.map((k,i)=>`<div class="ascendant-stat"><label for="stat-${k}"><b>${NAMES[i]}</b><small>${k}</small></label><button class="ascendant-lock ${ch.locks?.includes(k)?'on':''}" data-lock="${k}" aria-pressed="${!!ch.locks?.includes(k)}" aria-label="${ch.locks?.includes(k)?'Unlock':'Lock'} ${NAMES[i]}">${ch.locks?.includes(k)?'Lock':'Open'}</button><button data-step="${k}" data-delta="-1" aria-label="Decrease ${NAMES[i]}">−</button><input type="number" id="stat-${k}" data-stat="${k}" min="10" max="40" value="${s[k]}" inputmode="numeric" aria-label="${NAMES[i]}"><button data-step="${k}" data-delta="1" aria-label="Increase ${NAMES[i]}">+</button></div>`).join('')}</div><div class="ascendant-buttons"><button data-do="roll">Roll 10d4 / stat</button><button data-do="balance">Balance unlocked</button><button data-do="rollTeam">Roll entire team</button></div><div class="ascendant-mini-stats ascendant-derived" id="ascendant-derived">${derivedPanel(s)}</div>${rosterTools()}<p class="ascendant-muted">Locks preserve values during dice rolls and balancing; manual editing remains available. Each character must spend exactly 200 points. Every attribute is an integer from 10 to 40. Dice rolls are normalized to the same budget.</p></section><section class="ascendant-panel"><span class="ascendant-kicker">02 / ARENA</span><h2>${esc(chosenMap().name)}</h2><div class="ascendant-map-preview">${mapSVG(chosenMap())}</div><div class="ascendant-map-row"><button data-do="prevMap" aria-label="Previous map">‹</button><select id="ascendant-map" aria-label="Choose map">${MAPS.map((m,i)=>`<option value="${i}" ${i===mapId?'selected':''}>${i+1}. ${m.name}</option>`).join('')}</select><button data-do="nextMap" aria-label="Next map">›</button><button data-do="randomMap">Random</button></div>${arenaOptions()}<p class="ascendant-muted">Low cover: translucent obstacles · blue contours: ramps/high ground · gold: difficult terrain · orange: hazards. Map geometry is public; fog conceals enemy units and their actions.</p><p class="ascendant-muted">${chosenMap().w} × ${chosenMap().h} m · ${chosenMap().obstacles.length} obstacles · ${chosenMap().terrain.length} difficult terrain zones · ${chosenMap().elevation.length} raised areas · ${chosenMap().hazards.length} hazards · random deployment.</p><label class="ascendant-seed">Optional battle seed<input id="ascendant-seed" inputmode="numeric" placeholder="Random" value="${esc(seedInput)}"></label><button class="ascendant-primary ascendant-start" data-do="start" ${all?'':'disabled'}>Begin battle</button><p class="ascendant-muted">No classes, spells, equipment or special abilities. Mana is displayed but unused in this prototype.</p></section></main>`;}
const bar=(x,max,color)=>`<span class="ascendant-bar"><i style="width:${Math.max(0,Math.min(100,100*x/max))}%;background:${color}"></i></span>`;
function roster(team){return `<div class="ascendant-team ${team?'enemy':'ally'}"><div class="ascendant-team-label">${team?'TEAM B · AI':'TEAM A · YOU'}</div>${shownUnits().filter(u=>u.team===team).map(u=>`<button data-unit="${u.id}" class="ascendant-unit ${u.id===b.active?'active':''} ${u.id===inspectId?'selected':''} ${u.id===targetId?'target':''} ${u.hp<=0?'dead':''}"><span class="ascendant-unit-id">${u.id}</span><span class="ascendant-unit-main"><b>${esc(u.name)}</b>${bar(u.hp,u.max.hp,team?'#d77d75':'#7bc2e6')}<small>${Math.ceil(u.hp)}/${Math.ceil(u.max.hp)} HP · ${Math.max(0,u.next-b.time).toFixed(1)}s</small>${statusText(u)?`<small class="ascendant-status-line">${esc(statusText(u))}</small>`:''}</span></button>`).join('')}</div>`;}
function defenseTable(u){const profile=combatDefense(u);return `<details class="ascendant-defense-table"><summary>Damage defenses by type</summary><table><thead><tr><th>Damage type</th><th>DR</th><th>RES</th></tr></thead><tbody>${Object.entries(DAMAGE_TYPES).map(([k,n])=>`<tr><td>${n}</td><td>${profile[k].dr.toFixed(2)}</td><td>${(profile[k].res*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table><small>Includes active guard; situational reactions apply at impact.</small></details>`;}
function statusText(u){const items=conditionList(u).map(x=>`${x.label} ${x.model==='discrete'?'':Math.round(x.severity)}`.trim());if(u.grappledBy)items.push('Grappled by '+u.grappledBy);if(u.grappling)items.push('Holding '+u.grappling);if(u.hp<=0)items.push(u.dead?'Dead':'Down · unconscious');return items.join(' · ');}
function statusPanel(u){const items=conditionList(u),link=u.grappledBy||u.grappling;return `<div class="ascendant-conditions"><h4>Conditions</h4>${link?`<p class="ascendant-risk">${u.grappledBy?'Grappled by':'Holding'} ${esc(link)} · movement restricted until escape, release or separation.</p>`:''}${u.hp<=0?`<p>${u.dead?'Dead':'Incapacitated at zero Health; no in-battle revival.'}</p>`:''}${items.length?items.map(x=>`<div class="ascendant-condition"><span>${esc(x.label)}</span><b>${x.model==='discrete'?'Active':Math.round(x.severity)+' / 100'}</b>${bar(x.severity,100,'#d7b46f')}<small>${x.sources.map(e=>`${e.source?esc(e.source)+' · ':''}${e.remaining===null?'until removed':e.remaining.toFixed(1)+'s'}${e.decay?' · '+(e.decayMode==='proportional'?(e.decay*100).toFixed(0)+'%':e.decay)+'/s decay':''}`).join(' | ')||'Naturally recovering'}</small></div>`).join(''):'<p class="ascendant-muted">No active conditions.</p>'}<p class="ascendant-muted">Control ${(100*channel(u,'control')).toFixed(0)}% · movement ${(100*channel(u,'movement')).toFixed(0)}% · response ${(100*channel(u,'response')).toFixed(0)}%</p></div>`;}
function details(u){if(!visible(u))return '';const e=efficiencies(u),rates=recoveryRates(u);return `<div class="ascendant-detail"><div class="ascendant-section-title"><h3>${esc(u.name)} <small>${u.id}</small></h3><span>${u.hp<=0?'Down':u.guard?'Guarding':esc(phase(u))}</span></div>${[['Health','hp','#d77d75'],['Mana','mana','#6d9de0'],['Physical','physical','#69b89b'],['Mental','mental','#aa94de'],['Resolve','resolve','#d7b46f']].map(([n,k,col])=>`<div class="ascendant-resource"><span>${n}</span>${bar(u[k],u.max[k],col)}<small>${Math.round(u[k])}/${Math.round(u.max[k])}</small></div>`).join('')}<div class="ascendant-mini-stats">${KEYS.map(k=>`<span>${k} <b>${u.stats[k]}</b></span>`).join('')}</div><p class="ascendant-muted">DR ${u.max.dr.toFixed(1)} · RES ${(100*u.max.res).toFixed(1)}% · Physical ${(e.p*100).toFixed(0)}% · Mental ${(e.m*100).toFixed(0)}% · Resolve ${(e.w*100).toFixed(0)}%${u.off>0?` · Off-balance ${u.off.toFixed(0)}`:''} · Facing ${((u.facing*180/Math.PI+360)%360).toFixed(0)}° · Intercept ${engagementReady(u)?'ready':'spent'}</p><p class="ascendant-muted">${u.hp>0?`Current recovery/s: ${rates.physical.toFixed(2)} P · ${rates.mental.toFixed(2)} M · ${rates.resolve.toFixed(2)} R · ${rates.mana.toFixed(2)} Mana`:'No recovery while down.'} · Health and Mana have no low-resource penalty.</p>${b.map.schema?`<p class="ascendant-muted">Elevation ${groundAt(b.map,u).elevation.toFixed(2)} m · Surface stability ${Math.round(groundAt(b.map,u).stability*100)}% · Ground ${esc(groundAt(b.map,u).regions.join(", ")||"ordinary")} · ${b.units.filter(v=>v.team!==u.team&&visible(v)&&canSee(b.map,u,v)).length} individually detected opponents</p>`:""}${statusPanel(u)}${defenseTable(u)}</div>`;}
function previewText(p,key){if(!p)return '';const c=p.cost,base=`${Math.round(p.effort*100)}% effort · ${Math.round(p.ef*100)}% fatigue efficiency · ${c.physical.toFixed(1)} P · ${c.mental.toFixed(1)} M · ${c.resolve.toFixed(1)} R · ${p.delay.toFixed(2)}s (prep ${p.phases.preparation.toFixed(2)} / execute ${p.phases.execution.toFixed(2)} / recover ${p.phases.recovery.toFixed(2)})`;const f=p.forecast?.end,forecast=f?` · est. after action ${f.physical.toFixed(1)} P / ${f.mental.toFixed(1)} M / ${f.resolve.toFixed(1)} R`:"";if(!p.legal)return `${base} · select an eligible target`;if(p.control)return `${Math.round(p.hit*100)}% success · ${Math.round(p.strong*100)}% critical · ${p.severityRange?`Fear ${p.severityRange.map(x=>x.toFixed(0)).join("–")} on success`:p.control==='trip'?'Knock prone':p.control==='grapple'?'Restrict both characters':'Break restraint'} · ${base}${forecast}`;if(p.hit!==null)return `${Math.round(p.hit*100)}% hit · ${Math.round(p.strong*100)}% critical · ${Math.round(p.criticalFailure*100)}% critical fail · ${key==='shove'?`≤${p.shove.toFixed(1)} m push`:`${p.expected.toFixed(1)} expected damage · ${p.min.toFixed(1)}–${p.max.toFixed(1)} on hit · blunt · ${p.expectedRaw.toFixed(1)} raw − ${p.expectedReduced.toFixed(1)} DR − ${p.expectedResisted.toFixed(1)} RES (mean per attempt)${key==='heavy'?' · 1 + 8% DR pen / 10% RES pen':''}`} · ${base}${p.position?' · '+p.position.arc+(p.position.flank?' + flank':''):''}${p.reaction?' · response: '+p.reaction:''}${forecast}`;return base+forecast+(p.recovery?` · active recovery up to ${p.recovery.physical.toFixed(1)} P / ${p.recovery.mental.toFixed(1)} M / ${p.recovery.resolve.toFixed(1)} R (+ passive recovery)`:'');}
function damageDetail(q){if(!q)return '';const f=n=>Number(n).toFixed(2);return `<div class="ascendant-damage-detail"><b>Impact: ${f(q.raw)} raw → ${f(q.damage)} final</b>${q.parts.map(p=>`<div>${DAMAGE_TYPES[p.type]}: ${f(p.raw)} raw · DR ${f(p.dr)} → ${f(p.effectiveDR)} (${f(p.allocatedDR)} allocated, ${f(p.reduced)} prevented) · RES ${f(p.res*100)}% → ${f(p.effectiveRES*100)}% (${f(p.resisted)} prevented) · ${f(p.damage)} damage. Penetration: DR ${f(p.penetration.drFlat??0)} flat / ${f(100*(p.penetration.drRatio??0))}% proportional; RES ${f(100*(p.penetration.resFlat??0))} pp / ${f(100*(p.penetration.resRatio??0))}% proportional.</div>`).join('')}</div>`;}
function logDetail(d){if(!d)return '';const f=n=>Number(n).toFixed(2);return `<div class="ascendant-log-detail">${d.attack!==undefined?`d20 ${d.attack} − d20 ${d.defense} + modifier ${f(d.modifier)} = margin ${f(d.margin)} (hit ≥0, critical ≥12, critical failure ≤−12). ${d.outcome?esc(d.outcome):''}<br>`:''}${d.precision?`Precision: attack ${f(d.precision.attack)}, evasion ${f(d.precision.defense)}, base ${f(d.precision.base)}, position ${f(d.precision.position)}, terrain ${f(d.precision.environment??0)}, attack fatigue ${f(d.precision.attackerEfficiency)}, defense fatigue ${f(d.precision.defenderEfficiency)}, guard ${f(d.precision.guard)}, focus ${f(d.precision.focus)}, action ${f(d.precision.action)}, reaction ${f(d.precision.reaction??0)}.<br>`:''}${d.breakdown?`2d6 = ${d.dice}. ${damageDetail(d.breakdown)}`:d.raw!==undefined?`2d6 = ${d.dice}; raw ${f(d.raw)}; DR ${f(d.dr)} − penetration ${f(d.penetration)}; RES ${f(d.res*100)}%; final ${f(d.damage)}.<br>`:''}${d.cost?`Action cost${d.effort!==undefined?` (${Math.round(d.effort*100)}% effort)`:""}: ${f(d.cost.physical)} P / ${f(d.cost.mental)} M / ${f(d.cost.resolve)} R. ${Number.isFinite(d.efficiency)?`Efficiency ${f(d.efficiency*100)}%; next delay ${f(d.delay)}s.`:""}`:''}${d.distance!==undefined?`Distance ${f(d.distance)} m; turn cost ${f(d.turning)} m; terrain ${f(d.terrain??0)} m; ${esc(d.movementMode??'run')}; energy ${f(d.physicalCost)} P / ${f(d.mentalCost)} M / ${f(d.resolveCost)} R.`:''}${d.reaction?` Defensive response: ${esc(d.reaction)}.`:''}${d.phases?` Preparation ${f(d.phases.preparation)}s; execution ${f(d.phases.execution)}s; recovery ${f(d.phases.recovery)}s.`:''}${d.position?` Position: ${d.position.arc}${d.position.flank?' + flank':''} (+${d.position.bonus}).`: ''}${d.intercept?` Interception: ${d.damage.toFixed(1)} damage.`:''}${d.condition?` Condition: ${esc(d.condition)}${Number.isFinite(d.severity)?' · severity '+f(d.severity):''}${d.conditionRoll?' · d20 '+d.conditionRoll+' · resistance '+f(d.resistance):''}.`:''}${d.selfOffBalance!==undefined?` Critical failure: attacker off-balance ${f(d.selfOffBalance)}.`:''}${d.recovered?` Recovered ${d.recovered.map(f).join(' / ')} P/M/R.`:''}${d.displacement!==undefined?` Displacement ${f(d.displacement)} m; off-balance ${f(d.offBalance)}.`:''}</div>`;}
let expandedLogs=new Set();
function timelinePanel(){const rows=timelineRows(b).filter(u=>visible(b.units.find(v=>v.id===u.id))),horizon=Math.max(5,...rows.map(u=>u.end-b.time)),pct=t=>100*Math.max(0,Math.min(1,(t-b.time)/horizon)),segments=[['start','prepEnd','prep'],['prepEnd','impactAt','execute'],['impactAt','end','recovery']];return `<section class="ascendant-phase-panel"><div class="ascendant-section-title"><h3>Combat timeline</h3><span>Next ${horizon.toFixed(1)} s</span></div><div class="ascendant-phase-key"><span>Preparation</span><span>Execution</span><span>Recovery</span></div>${rows.map(u=>`<div class="ascendant-phase-row"><button data-unit="${u.id}" class="${u.team?'enemy':'ally'}">${u.id}</button><div class="ascendant-phase-track">${u.key?segments.filter(([a,z])=>u[z]>b.time&&u[z]>u[a]).map(([a,z,k])=>`<i class="${k}" style="left:${pct(u[a])}%;width:${Math.max(0,pct(u[z])-pct(u[a]))}%"></i>`).join(''):`<i class="ready" style="left:${pct(u.next)}%"></i>`}</div><small>${u.key?esc(u.key+' · '+u.phase):'ready '+Math.max(0,u.next-b.time).toFixed(1)+'s'}</small></div>`).join('')}<div class="ascendant-phase-key ascendant-muted">0 s <span>${(horizon/2).toFixed(1)} s</span> ${horizon.toFixed(1)} s</div><label class="ascendant-toggle"><input type="checkbox" id="ascendant-event-mode" ${b.eventMode?'checked':''}> Resolve one timeline event at a time</label></section>`;}
function replayPanel(){if(b.map.fog&&b.winner===null)return '<p class="ascendant-muted">Full replay and raw battle export unlock when combat ends (fog of war).</p>';const frames=b.frames||[];if(!frames.length)return '';const idx=replayIndex<0?frames.length-1:Math.min(replayIndex,frames.length-1),f=frames[idx];return `<details class="ascendant-replay" ${replayIndex>=0?'open':''}><summary>Recent timeline playback · ${frames.length} frames</summary><p class="ascendant-muted">Read-only event history; does not rewind the battle.</p><div class="ascendant-buttons"><button data-do="replayPrev" ${idx===0?'disabled':''}>Previous</button><button data-do="replayNext" ${idx===frames.length-1?'disabled':''}>Next</button><button data-do="replayLive">Latest</button></div><input id="ascendant-replay" type="range" min="0" max="${frames.length-1}" value="${idx}" aria-label="Timeline history frame"><p>${f.time.toFixed(2)}s · ${esc(f.label)}</p><svg viewBox="0 0 ${b.map.w} ${b.map.h}" aria-label="Recorded battlefield position"><rect width="${b.map.w}" height="${b.map.h}" fill="#253a36"/>${b.map.obstacles.map(o=>`<rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#78858a"/>`).join('')}${f.units.map((u,i)=>`<g opacity="${u.hp>0?1:.3}"><circle cx="${u.x}" cy="${u.y}" r=".55" fill="${i<5?'#79c4ee':'#e68179'}"/><text x="${u.x}" y="${u.y+.2}" font-size=".48" text-anchor="middle" fill="#102226">${esc(u.id)}</text></g>`).join('')}</svg></details>`;}
function renderBattle(){const c=actor(b),target=shownUnits().find(u=>u.id===targetId),ins=shownUnits().find(u=>u.id===inspectId)||(visible(c)?c:null),manual=c&&c.team===0&&!auto,check=path.length>1?pathCheck(b,path,push,moveKind):null,order=alive(b).filter(visible).sort((a,z)=>a.next-z.next||a.id.localeCompare(z.id));root.innerHTML=`${header(`${esc(b.map.name)} · map ${b.map.seed??0} · battle ${b.seed}`)}<main class="ascendant-battle"><section class="ascendant-panel ascendant-field"><div class="ascendant-section-title"><div><span class="ascendant-kicker">${b.winner!==null?'BATTLE COMPLETE':manual?'YOUR TURN':'SIMULATION'}</span><h2>${b.winner!==null?(b.winner===2?'Draw':b.winner===0?'Team A wins':'Team B wins'):esc(visible(c)?c.name:'Resolving timeline')}</h2></div><div class="ascendant-clock"><b>${b.time.toFixed(1)}s</b><small>Turn ${b.turns}</small></div></div><div class="ascendant-timeline" aria-label="Upcoming turns">${order.map(u=>`<button data-unit="${u.id}" class="${u.team?'enemy':'ally'} ${u===c?'on':''}"><b>${u.id}</b><small>${u.job?esc(u.job.key)+' · ':''}+${Math.max(0,u.next-b.time).toFixed(1)}s</small></button>`).join('')}</div><div class="ascendant-board-wrap">${mapSVG(b.map,true)}</div>${timelinePanel()}<div class="ascendant-board-tools"><button data-do="modeMove" class="${mode==='move'?'on':''}">Path</button><button data-do="modeRoute" class="${mode==='route'?'on':''}" ${!manual||b.moved||(c&&budget(c,push,moveKind)<=0)?'disabled':''}>Auto path</button><button data-do="modeFace" class="${mode==='face'?'on':''}" ${!manual?'disabled':''}>Face</button><button data-do="modePan" class="${mode==='pan'?'on':''}">Pan</button><button data-do="zoomIn" aria-label="Zoom in">+</button><button data-do="zoomOut" aria-label="Zoom out">−</button><button data-do="resetView">Fit</button><button data-do="centerActive">Center active</button><button data-do="jumpActions">Actions ↓</button><span class="ascendant-muted">1 grid = 1 m · ${b.map.fog?"Fog enabled":"Full view"}</span></div><div class="ascendant-overlay-tools"><label class="ascendant-toggle"><input type="checkbox" id="ascendant-reach" ${showReach?'checked':''}> Direct reach (approx.)</label><label class="ascendant-toggle"><input type="checkbox" id="ascendant-threat" ${showThreat?'checked':''}> Threat ranges</label>${b.map.fog?`<label>Visibility shading <select id="ascendant-sight"><option value="team" ${sightView==='team'?'selected':''}>Team</option><option value="individual" ${sightView==='individual'?'selected':''}>Inspected ally</option></select></label>`:""}</div><div class="ascendant-legend"><span>Gold: active</span><span>White: inspected</span><span>Orange dashed: target</span><span>Darkened: not visible · ?: last seen</span><span>Blue contour: elevation</span><span>Gold: difficult ground</span></div>${mode==='face'&&manual?'<p class="ascendant-muted">Facing mode: tap ground or a character, then choose your action.</p>':''}${visible(c)?movementPanel(c,manual,check):`<p class="ascendant-muted">Timeline advancing.</p>`}${note?`<p class="ascendant-message" role="status">${esc(note)}</p>`:''}<div class="ascendant-teams">${roster(0)}${roster(1)}</div></section><section class="ascendant-panel ascendant-controls"><div class="ascendant-section-title"><span class="ascendant-kicker">ACTION CONTROL</span><button data-do="jumpBoard">Battlefield ↑</button></div><h2>${manual?esc(c.name):b.winner!==null?'Battle finished':c?'AI turn':'Pending timeline events'}</h2><div class="ascendant-target">Target: <b>${target?esc(target.name):'None'}</b>${target?'<button data-do="clearTarget">Clear</button>':''}${target&&c?` · ${dist(c,target).toFixed(1)} m`:''}</div><div class="ascendant-exertion"><label>Effort <select id="ascendant-effort" ${!manual?'disabled':''}>${[.5,.6,.7,.8,.9,1].map(v=>`<option value="${v}" ${Math.abs(push.effort-v)<.001?'selected':''}>${Math.round(v*100)}%${v===1?' · Full':v===.5?' · Conservative':''}</option>`).join('')}</select></label><label>Resolve support <select id="ascendant-push" ${!manual?'disabled':''}>${[['none','None'],['physical','Physical'],['mental','Mental'],['both','Both']].map(([k,n])=>`<option value="${k}" ${push.push===k?'selected':''}>${n}</option>`).join('')}</select></label><small>Lower effort conserves energy at reduced output. Resolve offsets fatigue only in relevant channels; it cannot exceed available reserves. End-of-action forecasts exclude enemy interference.</small></div><div class="ascendant-reaction"><label>Defensive reaction <select id="ascendant-reaction" ${!manual?'disabled':''}>${Object.entries(REACTIONS).map(([k,v])=>`<option value="${k}" ${c?.reaction===k?'selected':''}>${v}</option>`).join('')}</select></label><small>One reaction per turn, shared with interception. Dodge evades; block absorbs; parry deflects; brace hardens; counter retaliates. Rear attacks and committed strikes can prevent responses.</small></div><div class="ascendant-actions">${Object.entries(ACTIONS).map(([k,a])=>`<button data-action="${k}" ${!manual||!canAct(b,k,target)?'disabled':''}><b>${a.label}</b><small>${esc(previewText(manual?previewAction(b,k,target,push):null,k))}</small></button>`).join('')}</div><p class="ascendant-muted">Commit movement once, then act after movement resolves. Other characters may act in between. Forecasts use the current state; range, facing, defense, and reactions may change before impact. Heavy strikes resist ordinary interruptions after preparation. Hold for enemy waits for engagement or times out.</p><div class="ascendant-ai-tools"><label class="ascendant-toggle"><input type="checkbox" id="ascendant-auto" ${auto?'checked':''}> Auto-play both</label><button data-do="pause" ${b.winner!==null?'disabled':''}>${paused?'Resume AI':'Pause AI'}</button><button data-do="step" ${(!paused&&!manual)||b.winner!==null?'disabled':''}>${c?"AI step":"Step event"}</button><label>Speed <select id="ascendant-speed"><option value="650" ${delay===650?'selected':''}>Slow</option><option value="300" ${delay===300?'selected':''}>Normal</option><option value="40" ${delay===40?'selected':''}>Fast</option></select></label></div>${details(ins)}${replayPanel()}<div class="ascendant-section-title"><h3>Battle log</h3><button data-do="log">${showLog?'Recent':'Full log'}</button><button data-do="export" ${b.map.fog&&b.winner===null?"disabled":""}>Export</button></div><div class="ascendant-log">${b.log.filter(l=>!b.map.fog||b.winner!==null||l.visible!==false).slice(showLog?-1000:-12).map((l,i)=>({l,i:b.log.length-Math.min(b.log.length,showLog?1000:12)+i})).reverse().map(({l,i})=>l.detail?`<details data-log-id="${l.t}:${i}" ${expandedLogs.has(`${l.t}:${i}`)?'open':''}><summary><time>${l.t.toFixed(1)}s</time> ${esc(l.text)}</summary>${logDetail(l.detail)}</details>`:`<p><time>${l.t.toFixed(1)}s</time> ${esc(l.text)}</p>`).join('')||'<p>Battle has begun.</p>'}</div><div class="ascendant-buttons ascendant-restart"><button data-do="restart">Restart same seed</button><button data-do="rematch">New random seed</button></div>${storageNote?`<p class="ascendant-message">${esc(storageNote)}</p>`:''}</section></main>`;bindBoard();schedule();}
function refreshSetup(){const c=teams[tab][edit],t=total(c.stats),n=teams.flat().filter(c=>valid(c.stats)).length;root.querySelector('#ascendant-left').textContent=200-t;root.querySelector('#ascendant-left').className=t===200?'ascendant-good':'ascendant-warn';root.querySelector('.ascendant-start').disabled=n!==10;const pill=root.querySelector('.ascendant-pill');pill.textContent=`${n}/10 ready`;pill.className='ascendant-pill '+(n===10?'ok':'warn');const tile=root.querySelector(`[data-edit="${edit}"]`);tile.querySelector('b').textContent=c.name;tile.querySelector('small').textContent=`${t} / 200 ${valid(c.stats)?'✓':''}`;root.querySelector('#ascendant-derived').innerHTML=derivedPanel(c.stats);}
function render(){const y=window.scrollY,logY=root.querySelector('.ascendant-log')?.scrollTop||0;if(b){saveBattle();renderBattle();const log=root.querySelector('.ascendant-log');if(log)log.scrollTop=logY;}else renderSetup();window.scrollTo(0,y);}
function schedule(){clearTimeout(timer);timer=null;const c=b&&actor(b);if(b&&b.winner===null&&!paused&&!document.hidden&&(!c||c.team===1||auto)){timer=setTimeout(()=>{if(c)aiTurn(b);else stepTimeline(b);newTurn();},delay);}}
function newTurn(){path=[];waypoint=-1;moveKind='run';if(mode==='face'||mode==='route')mode='move';push=exertion(false);note='';const c=actor(b);inspectId=visible(c)?c.id:(shownUnits().find(u=>u.team===0&&u.hp>0)?.id||inspectId);targetId=null;replayIndex=-1;render();}
function selectUnit(id){const u=b.units.find(u=>u.id===id);if(!visible(u))return;inspectId=id;if(u&&actor(b)&&u.team!==actor(b).team&&u.hp>0)targetId=id;render();}
function start(seed,replay=false){save();const selected=replay?clone(initial):clone(teams),map=replay?b.map:chosenMap();initial=selected;b=newBattle(selected,map,seed);view=null;paused=false;auto=false;mode='move';moveKind='run';waypoint=-1;expandedLogs.clear();newTurn();window.scrollTo(0,0);}
function changeView(scale){const m=b.map,v=view||{x:0,y:0,w:m.w,h:m.h},w=Math.min(m.w,Math.max(6,v.w*scale)),h=w*m.h/m.w;view={x:Math.max(0,Math.min(m.w-w,v.x+(v.w-w)/2)),y:Math.max(0,Math.min(m.h-h,v.y+(v.h-h)/2)),w,h};render();}
